func findRepeatedDnaSequences(s string) []string {
	hashCode := map[byte]int{'A': 0, 'C': 1, 'G': 2, 'T': 3}
	ans, cnt, left, right := []string{}, map[int]int{}, 0, 0

	sha, multi := 0, int(math.Pow(4, 9))
	for ; right < len(s); right++ {
		sha = sha*4 + hashCode[s[right]]
		if right-left+1 < 10 {
			continue
		}
		cnt[sha]++
		if cnt[sha] == 2 {
			ans = append(ans, s[left:right+1])
		}
		sha, left = sha-multi*hashCode[s[left]], left+1
	}
	return ans
}

vector<string> findRepeatedDnaSequences(string s) {
    int N = s.size();
    unordered_map<long long,int> hash;
    vector<string> ans;

    if (N <= 10) return ans;
    long long p = 5, h = 0, M = 1e9 + 7, d = 1;

    for (int i = N - 1; i >= 0; i--) {
        h = (h * p) % M + (s[i] - 'A' + 1) % M;

        if (i + 10 >= N) {
            d = (d * p)  % M;
        } else {
            h = (h - ((s[i + 10] - 'A' + 1) * d) % M + M) % M;
        }

        if (hash.find(h) != hash.end() && hash[h] == 1) {
            ans.push_back(s.substr(i, 10));
        }
        hash[h]++;
    }
    return ans;
}

